/**
 * @param {CardSeed} seed
 */
function buildPrompts(seed) {
  const pro = PRO_PROMPTS[seed.id];
  if (!pro?.zh || !pro?.en) {
    throw new Error(`missing_pro_prompt:${seed.id}`);
  }
  return { prompt_zh: pro.zh, prompt_en: pro.en };
}

const missingPro = assertProPromptCoverage(SEEDS.map((s) => s.id));
if (missingPro.length) {
  console.error('missing pro prompts:', missingPro.join(', '));
  process.exit(1);
}

const cards = SEEDS.map((seed) => {
  const { prompt_zh, prompt_en } = buildPrompts(seed);
  return {
    id: seed.id,
    section_id: seed.section_id,
    name_zh: seed.name_zh,
    name_en: seed.name_en,
    annotation_zh: seed.annotation_zh,
    annotation_en: seed.annotation_en,
    badge_zh: seed.badge_zh,
    badge_en: seed.badge_en,
    hub_binding: seed.hub_binding,
    binding_kind: seed.binding_kind,
    fallback_binding: seed.fallback_binding ?? null,
    deps: seed.deps,
    must_deliver: seed.must_deliver,
    primary_deliverable: seed.primary_deliverable,
    prompt_zh,
    prompt_en,
    star: seed.star,
    priority: seed.priority,
    sort_order: seed.sort_order,
  };
});

